const input = $('When Called').first().json || {};
const config = $('Load Config').first().json || {};

let mode = (input.mode || 'n8n_users').toString().trim();
if (!['n8n_users', 'volunteers', 'non_users', 'csv'].includes(mode)) mode = 'n8n_users';

let filters = input.filters || {};
if (typeof filters === 'string') { try { filters = JSON.parse(filters); } catch (e) { filters = {}; } }
if (typeof filters !== 'object' || Array.isArray(filters) || filters === null) filters = {};

// Cap: maxSampleSize for the wizard audiences, csvMaxInvites for CSV uploads (0 / empty = invite everyone found, up to the cap)
const maxSampleSize = mode === 'csv' ? (Number(config.csvMaxInvites) || 200) : (Number(config.maxSampleSize) || 20);
let sampleSize = Number(input.sampleSize);
if (!Number.isFinite(sampleSize) || sampleSize <= 0) sampleSize = maxSampleSize;
if (sampleSize > maxSampleSize) sampleSize = maxSampleSize;
sampleSize = Math.floor(sampleSize);

// Cooldown window: Config cooldownDays is the source of truth. The declared input arrives as null when the caller omits it
// (Number(null) === 0 would silently disable the client-side check), so anything not a positive number falls back.
const rawWindow = input.excludeRecentDays;
let excludeRecentDays = (rawWindow === null || rawWindow === undefined || rawWindow === '' || typeof rawWindow === 'boolean') ? NaN : Number(rawWindow);
if (!Number.isFinite(excludeRecentDays) || excludeRecentDays <= 0) excludeRecentDays = Number(config.cooldownDays) || 60;
excludeRecentDays = Math.floor(excludeRecentDays);

return [{ json: { mode, filters, sampleSize, excludeRecentDays, config } }];

const data = $input.first().json;
const { filters, sampleSize, excludeRecentDays, config } = data;
let mode = data.mode;

const cooldownField = config.cooldownField || 'last_user_research_invite_date';
const shardField = config.shardField || 'uxr_shard';
const shardCount = Number(config.shardCount) || 4096;
const cooldownSegmentId = Number(config.cooldownSegmentId) || 0;
const cutoffTs = Math.floor((Date.now() - excludeRecentDays * 24 * 60 * 60 * 1000) / 1000);

// CSV mode: the researcher supplied the emails. Verify them in Customer.io (chunks of 50 emails per query),
// exclude the cooldown segment server-side; unsubscribed handling happens in Format Output (webform people are exempt).
if (mode === 'csv') {
  const raw = Array.isArray(filters.emails) ? filters.emails : [];
  const emails = Array.from(new Set(raw.map(e => String(e || '').trim().toLowerCase()).filter(e => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e))));
  const chunks = [];
  for (let i = 0; i < emails.length; i += 50) chunks.push(emails.slice(i, i + 50));
  if (!chunks.length) chunks.push(['nobody@invalid.invalid']); // matches nothing, keeps the loop shape
  const base = [];
  if (cooldownSegmentId > 0) base.push({ not: { segment: { id: cooldownSegmentId } } });
  return [{ json: {
    mode, filters: { csv: emails.length }, sampleSize, excludeRecentDays,
    cooldownField, cooldownCutoffTs: cutoffTs, cooldownSegmentId, shardField, shardCount, noShards: false,
    csvMode: true, csvEmails: emails, csvChunks: chunks,
    baseAndClauses: base,
    attempt: 0, maxAttempts: chunks.length, shardsUsed: [], collected: [], totalMatching: 0
  } }];
}

// Audiences: n8n_users (Customer.io cloud accounts) and volunteers (research webform, includes non-users).
// 'non_users' is kept as an alias: volunteers with n8n_usage restricted to aware + new.
const base = config.volunteerBaseQuery || config.nonUserBaseQuery || {};
const userFilters = Object.assign({}, filters || {});
if (mode === 'non_users') {
  mode = 'volunteers';
  if (!Array.isArray(userFilters.n8n_usage) || userFilters.n8n_usage.length === 0) userFilters.n8n_usage = base.non_users_usage || ['aware', 'new'];
}
const filterDefs = mode === 'n8n_users' ? (config.nUserFilters || []) : (config.volunteerFilters || config.nonUserFilters || []);
const defById = {};
for (const d of filterDefs) defById[d.id] = d;

const andClauses = [];
if (mode === 'n8n_users') {
  // Quality gates (unsubscribed always excluded for n8n users)
  andClauses.push({ attribute: { field: 'email', operator: 'exists' } });
  andClauses.push({ not: { attribute: { field: 'unsubscribed', operator: 'eq', value: 'true' } } });
  andClauses.push({ attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } });
  andClauses.push({ attribute: { field: 'confirmed', operator: 'eq', value: 'true' } });
  // Default: everyone except deleted accounts, unless the researcher chose plan statuses explicitly
  const chosenStatus = userFilters.cloud_plan_status;
  if (!Array.isArray(chosenStatus) || chosenStatus.length === 0) {
    andClauses.push({ not: { attribute: { field: 'cloud_plan_status', operator: 'eq', value: 'deleted' } } });
  }
} else {
  // Volunteers: the research form is the consent. It sets unsubscribed = true on everyone (no marketing), so that flag is NOT a gate here.
  andClauses.push({ attribute: { field: 'email', operator: 'exists' } });
  andClauses.push({ attribute: { field: 'origin', operator: 'eq', value: base.origin || 'user_research_webform' } });
}

// Cooldown, server-side: not in the Customer.io cooldown segment (id from Config). Client-side date check stays in Format Output.
if (cooldownSegmentId > 0) andClauses.push({ not: { segment: { id: cooldownSegmentId } } });

// Researcher filters. Values are option values; a def may map them to several attribute values (matchValues),
// to segments (via: 'segment'), and an option may add extra conditions (clauses), e.g. Trial + status trialing.
// Options of one filter are OR-ed together; filters are AND-ed.
const applied = {};
for (const [key, raw] of Object.entries(userFilters)) {
  const vals = (Array.isArray(raw) ? raw : [raw]).filter(v => v !== undefined && v !== null && v !== '');
  if (vals.length === 0) continue;
  const def = defById[key];
  if (def && def.enabled === false) continue; // not live yet (needs Customer.io segments)
  const field = (def && def.field) || key;
  if (def && def.via === 'segment') {
    const ids = vals.map(v => { const o = (def.options || []).find(x => x.value === v); return o && o.segmentId; }).filter(Boolean);
    if (ids.length) andClauses.push({ or: ids.map(id => ({ segment: { id: Number(id) } })) });
    applied[key] = vals;
    continue;
  }
  const groups = [];
  for (const v of vals) {
    const o = def && (def.options || []).find(x => x.value === v);
    const values = (o && Array.isArray(o.matchValues) && o.matchValues.length) ? o.matchValues : [String(v)];
    const valueClause = values.length === 1 ? { attribute: { field, operator: 'eq', value: values[0] } } : { or: values.map(x => ({ attribute: { field, operator: 'eq', value: x } })) };
    const extra = (o && Array.isArray(o.clauses)) ? o.clauses : [];
    groups.push(extra.length ? { and: [valueClause].concat(extra) } : valueClause);
  }
  andClauses.push(groups.length === 1 ? groups[0] : { or: groups });
  applied[key] = vals;
}

// Volunteers are ~1,000 people: one paginated query, no shards.
const noShards = mode === 'volunteers';

return [{ json: {
  mode, filters: applied, sampleSize, excludeRecentDays,
  cooldownField, cooldownCutoffTs: cutoffTs, cooldownSegmentId, shardField, shardCount, noShards, csvMode: false,
  baseAndClauses: andClauses,
  attempt: 0, maxAttempts: 3, shardsUsed: [], collected: [], totalMatching: 0
} }];

const s = $input.first().json;

if (s.csvMode) {
  // CSV: each attempt verifies one chunk of emails (OR of email eq), no shards
  const chunk = (s.csvChunks || [])[s.attempt || 0] || ['nobody@invalid.invalid'];
  const emailClause = chunk.length === 1 ? { attribute: { field: 'email', operator: 'eq', value: chunk[0] } } : { or: chunk.map(e => ({ attribute: { field: 'email', operator: 'eq', value: e } })) };
  return [{ json: { ...s, currentShards: [], shardsUsed: [], cioFilter: { filter: { and: s.baseAndClauses.concat([emailClause]) } } } }];
}

if (s.noShards) {
  // Small pool: query everyone matching the base filter, no shard clause
  return [{ json: { ...s, currentShards: [], shardsUsed: [], cioFilter: { filter: { and: s.baseAndClauses.slice() } } } }];
}

// Number of shards to query this attempt. Start with a spread proportional to sampleSize, widen on retries.
const shardsPerAttempt = Math.min(s.shardCount, Math.max(4, s.sampleSize) * (s.attempt + 1) * 2);

const used = new Set(s.shardsUsed || []);
const newShards = [];
let guard = 0;
while (newShards.length < shardsPerAttempt && used.size < s.shardCount && guard < shardsPerAttempt * 20) {
  guard++;
  const shard = Math.floor(Math.random() * s.shardCount);
  if (!used.has(shard)) { used.add(shard); newShards.push(shard); }
}

// Build the full CIO filter with a shard OR-clause for the newly picked shards
const shardClause = { or: newShards.map(sh => ({ attribute: { field: s.shardField, operator: 'eq', value: String(sh) } })) };
const andClauses = s.baseAndClauses.slice();
if (newShards.length > 0) andClauses.push(shardClause);

const cioFilter = { filter: { and: andClauses } };

return [{ json: { ...s, currentShards: newShards, shardsUsed: Array.from(used), cioFilter } }];

const s = $('Pick Shards').first().json;
const pages = $input.all().map(i => i.json);

let error = null;
let rows = [];
for (const p of pages) {
  if (p.error) {
    error = 'Customer.io request failed: ' + (typeof p.error === 'string' ? p.error : (p.error.message || JSON.stringify(p.error).slice(0, 200)));
    continue;
  }
  const status = p.statusCode || 0;
  const body = p.body || p;
  if (status >= 400) {
    error = 'Customer.io API error (HTTP ' + status + '): ' + JSON.stringify(body).slice(0, 300);
    continue;
  }
  const ids = (body && (body.identifiers || body.results || body.customers)) || [];
  if (Array.isArray(ids)) rows = rows.concat(ids);
}

const prior = Array.isArray(s.collected) ? s.collected : [];
const byId = new Map();
for (const r of prior) { const k = r.cio_id || r.id || r.email; if (k) byId.set(k, r); }
for (const r of rows) { const k = r.cio_id || r.id || r.email; if (k && !byId.has(k)) byId.set(k, r); }
const collected = Array.from(byId.values());

const attempt = (s.attempt || 0) + 1;
const enough = collected.length >= s.sampleSize;
const exhausted = attempt >= (s.maxAttempts || 3);
// noShards: one paginated pass over the whole pool is the full answer. csvMode: walk every chunk, never stop early.
const done = s.noShards || (s.csvMode ? (exhausted || !!error) : (enough || exhausted || !!error));

return [{ json: { ...s, attempt, collected, collectedCount: collected.length, totalMatching: collected.length, error, done } }];

const s = $('Collect & Check').first().json;
const samples = $('Sample Candidates').all().map(i => i.json).filter(x => x && !x.__empty);
const fetched = $('Fetch Attributes').all().map(i => i.json);
const cfg = $('Load Config').first().json || {};
const cioUrlTemplate = String(cfg.cioProfileUrlTemplate || '');
function hasAttrs(resp) { return !!(resp && resp.customer && resp.customer.attributes && typeof resp.customer.attributes === 'object' && !Array.isArray(resp.customer.attributes)); }
function attrsOf(resp) { return hasAttrs(resp) ? resp.customer.attributes : {}; }
const cooldownField = s.cooldownField || 'last_user_research_invite_date';
const cutoffTs = Number(s.cooldownCutoffTs) || 0;
const emailKey = value => String(value || '').trim().toLowerCase();

// PER-PERSON RULES (Giulio, 2026-10-07). One person = one email = possibly several Customer.io profiles.
// Cooldown: if ANY profile of the email was invited inside the window (date on the profile, or membership of the cooldown segment), skip the person.
// Unsubscribe: the person can be invited when at least one profile is not unsubscribed, or at least one comes from the research webform.
//   Blocked only when every profile is unsubscribed and none is a webform sign-up.
// Unsubscribed is read from both places Customer.io reports it: the profile status and the attribute.
function facts(resp) {
  const known = hasAttrs(resp);
  const a = attrsOf(resp);
  const lastInvite = Number(a[cooldownField]) || 0;
  return {
    known,
    unsub: known && (resp.customer.unsubscribed === true || String(a.unsubscribed) === 'true'),
    webform: known && a.origin === 'user_research_webform',
    recent: lastInvite > 0 && lastInvite >= cutoffTs
  };
}

// The duplicate lookups must have worked: without them the per-person rules cannot be applied, so fail visibly instead of inviting blind.
function pageProblem(p) {
  if (!p) return 'no response';
  if (p.error) return typeof p.error === 'string' ? p.error : (p.error.message || JSON.stringify(p.error).slice(0, 200));
  const status = Number(p.statusCode) || 0;
  if (status < 200 || status >= 300) return 'HTTP ' + status + ': ' + JSON.stringify(p.body || {}).slice(0, 200);
  return null;
}
const lookupPages = $('Lookup Profiles By Email').all().map(i => i.json);
const cooldownPages = $('Lookup Cooldown By Email').all().map(i => i.json);
if (samples.length) {
  const problem = lookupPages.concat(cooldownPages).map(pageProblem).find(Boolean) || (lookupPages.length && cooldownPages.length ? null : 'no response');
  if (problem) {
    const msg = 'Customer.io duplicate-profile check failed (' + problem + ')';
    return [{ json: { error: msg, candidates: [], sampleSize: 0, collectedCount: 0, totalMatchingEstimate: 0, mode: s.mode, filtersApplied: s.filters, shardsUsed: s.shardsUsed || [], message: 'Search failed: ' + msg } }];
  }
}

// Every profile we know about, grouped by email: the sampled ones plus their siblings
const byEmail = new Map();
function addProfile(key, f, sampled) {
  if (!key) return;
  if (!byEmail.has(key)) byEmail.set(key, []);
  byEmail.get(key).push({ ...f, sampled });
}
let cooldownDropped = 0, fetchFailed = 0, duplicateEmailsDropped = 0, unsubscribedDropped = 0, cooldownDroppedBySibling = 0, duplicateCheckFailed = 0;
const all = samples.map((sm, idx) => {
  const resp = fetched[idx] || {};
  const a = attrsOf(resp);
  if (!hasAttrs(resp)) fetchFailed++;
  const usage_summary = [
    a.successful_prod_exec_workflows !== undefined ? 'prod wfs: ' + a.successful_prod_exec_workflows : null,
    a.services_count !== undefined ? 'services: ' + a.services_count : null,
    a.ai_active_wfs !== undefined ? 'AI wfs: ' + a.ai_active_wfs : null
  ].filter(Boolean).join(', ');
  const f = facts(resp);
  const cioId = sm.cio_id || null;
  const email = a.email || sm.email || null;
  addProfile(emailKey(email), f, true);
  return {
    email,
    id: sm.cio_id || sm.cust_id || null,
    cio_id: cioId,
    cio_url: (cioId && cioUrlTemplate.indexOf('{cio_id}') !== -1) ? cioUrlTemplate.replace('{cio_id}', cioId) : null,
    first_name: a.first_name || null,
    country: a.country || null,
    cloud_plan: a.cloud_plan || null,
    cloud_plan_status: a.cloud_plan_status || null,
    role: a.job_role || a.utm_user_role || null,
    company_size: a.company_size || null,
    n8n_usage: a.n8n_usage || null,
    tech_skills: a.tech_skills || null,
    work_role: a.work_role || null,
    linkedin: a.linkedin || null,
    usage_summary,
    attributes_fetched: hasAttrs(resp),
    __recentlyInvited: f.recent,
    __selfBlocked: f.unsub && !f.webform
  };
});
const siblingPicks = $('Pick Siblings').all().map(i => i.json);
const siblingFetched = $input.all().map(i => i.json);
siblingPicks.forEach((p, idx) => { if (p && !p.__none && p.cio_id) addProfile(emailKey(p.email), facts(siblingFetched[idx] || {}), false); });
const lookupEmails = new Set();
for (const p of lookupPages) {
  const ids = (p && p.body && p.body.identifiers) || [];
  if (Array.isArray(ids)) for (const r of ids) { const k = emailKey(r && r.email); if (k) lookupEmails.add(k); }
}
const cooldownEmails = new Set();
for (const p of cooldownPages) {
  const ids = (p && p.body && p.body.identifiers) || [];
  if (Array.isArray(ids)) for (const r of ids) { const k = emailKey(r && r.email); if (k) cooldownEmails.add(k); }
}

const duplicateProfileEmails = Array.from(byEmail, ([email, ps]) => ({ email, profileCount: ps.length })).filter(r => r.profileCount > 1);
const unsubscribeConflictEmails = Array.from(byEmail).filter(([, ps]) => ps.some(p => p.known && p.unsub && !p.webform) && ps.some(p => p.known && !p.unsub)).map(([email]) => email);

// One person can be sampled through several profiles. People keep their (random) sample order; within a person, the profile that is
// itself invitable and carries the most details goes first: it represents the person on the card, in the email greeting and for the stamp.
const richness = c => ['cloud_plan', 'first_name', 'role', 'company_size', 'usage_summary', 'n8n_usage', 'tech_skills', 'country'].filter(k => c[k]).length + (c.attributes_fetched ? 1 : 0);
const people = new Map();
all.forEach((c, idx) => { const k = (c.email ? emailKey(c.email) : '') || ('#' + idx); if (!people.has(k)) people.set(k, []); people.get(k).push(c); });
const ordered = [];
for (const profiles of people.values()) ordered.push(...profiles.slice().sort((a, b) => (Number(a.__selfBlocked) - Number(b.__selfBlocked)) || (richness(b) - richness(a))));
const seenEmails = new Set();
// People (distinct emails) skipped, by reason, for the card
const cooldownPeople = new Set(), unsubscribedPeople = new Set();
const eligible = ordered.filter(c => {
  const key = c.email ? emailKey(c.email) : null;
  const ps = (key && byEmail.get(key)) || [];
  if (c.__recentlyInvited) { cooldownDropped++; if (key) cooldownPeople.add(key); return false; }
  if (key && (cooldownEmails.has(key) || ps.some(p => p.recent))) { cooldownDropped++; cooldownDroppedBySibling++; cooldownPeople.add(key); return false; }
  // CSV: no attributes = unsubscribed status unknown -> fail closed (counted in fetchFailed). Other audiences passed the server-side gates.
  if (s.csvMode && !c.attributes_fetched) return false;
  if (c.attributes_fetched && !ps.some(p => p.known && (!p.unsub || p.webform))) { unsubscribedDropped++; if (key) unsubscribedPeople.add(key); return false; }
  // A sibling we could not read may hide a recent invite: skip the person rather than guess
  if (ps.some(p => !p.sampled && !p.known)) { duplicateCheckFailed++; return false; }
  // Exactly one mailbox: a malformed 'a@x.com,b@y.com' value would reach SMTP as two recipients
  if (!key || !/^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$/.test(key)) return false;
  if (seenEmails.has(key)) { duplicateEmailsDropped++; return false; }
  seenEmails.add(key);
  return true;
});
const candidates = eligible.slice(0, s.sampleSize).map(c => { const { __recentlyInvited, __selfBlocked, ...rest } = c; return rest; });
const shardsWalked = Array.isArray(s.shardsUsed) ? s.shardsUsed.length : 0;
const exact = !!s.noShards || !!s.csvMode;
const poolEstimate = exact ? (s.collectedCount || 0) : (shardsWalked > 0 ? Math.round((s.collectedCount || 0) * (s.shardCount || 4096) / shardsWalked) : (s.collectedCount || 0));
// CSV stats count distinct emails, not profiles (one address may have several Customer.io profiles)
let csvStats = null;
if (s.csvMode) {
  const total = (s.csvEmails || []).length;
  const foundEmails = new Set((Array.isArray(s.collected) ? s.collected : []).map(r => emailKey(r.email)).filter(Boolean));
  // Per-person breakdown of the uploaded emails. An email the search did not return is either in cooldown on every profile or absent from Customer.io.
  const uploaded = (s.csvEmails || []).map(emailKey).filter(Boolean);
  for (const e of uploaded) if (cooldownEmails.has(e)) cooldownPeople.add(e);
  const selectedEmails = new Set(candidates.map(c => emailKey(c.email)));
  const sampledEmails = new Set(all.map(c => emailKey(c.email)).filter(Boolean));
  const skippedNotFound = uploaded.filter(e => !lookupEmails.has(e) && !sampledEmails.has(e)).length;
  const overCap = Math.max(0, eligible.length - candidates.length);
  const notExamined = uploaded.filter(e => foundEmails.has(e) && !sampledEmails.has(e) && !cooldownPeople.has(e)).length;
  const skippedOther = Math.max(0, total - selectedEmails.size - cooldownPeople.size - unsubscribedPeople.size - skippedNotFound - overCap - notExamined);
  csvStats = { total, found: foundEmails.size, notFoundOrCooldown: Math.max(0, total - foundEmails.size), unsubscribedDropped, fetchFailed, profilesMatched: s.collectedCount || 0, duplicateProfileEmails, unsubscribeConflictEmails, profilesChecked: samples.length, selected: candidates.length,
    skippedCooldown: cooldownPeople.size, skippedUnsubscribed: unsubscribedPeople.size, skippedNotFound, skippedOther, overCap, notExamined };
}
// Researcher filters with the labels from UXR Config, for the candidate card (the raw keys are in filtersApplied)
const filterDefs = (s.mode === 'n8n_users' ? cfg.nUserFilters : (cfg.volunteerFilters || cfg.nonUserFilters)) || [];
const filterLabels = s.csvMode ? [] : Object.entries(s.filters || {}).map(([key, raw]) => {
  const def = Array.isArray(filterDefs) ? filterDefs.find(d => d && d.id === key) : null;
  const values = (Array.isArray(raw) ? raw : [raw]).map(v => { const o = def && (def.options || []).find(x => x.value === v); return (o && o.label) || String(v); });
  return { label: (def && def.label) || key, values };
});
return [{ json: {
  candidates, sampleSize: candidates.length, requestedSize: s.sampleSize,
  collectedCount: s.collectedCount || 0, cooldownDropped, cooldownDroppedBySibling, fetchFailed, duplicateEmailsDropped, unsubscribedDropped, duplicateCheckFailed,
  emailsWithSeveralProfiles: duplicateProfileEmails.length,
  peopleSkippedCooldown: cooldownPeople.size, peopleSkippedUnsubscribed: unsubscribedPeople.size, unsubscribeConflictEmails,
  totalMatchingEstimate: exact && s.csvMode ? (csvStats ? csvStats.found : 0) : poolEstimate, poolIsExact: exact,
  csvStats, csvEmails: s.csvMode ? (s.csvEmails || []) : undefined,
  mode: s.mode, filtersApplied: s.filters, filterLabels, shardsUsed: s.shardsUsed || [], error: null
} }];

const s = $input.first().json;
// Rebuild the state for another Pick Shards pass. baseAndClauses persists.
return [{ json: {
  mode: s.mode, filters: s.filters, sampleSize: s.sampleSize, excludeRecentDays: s.excludeRecentDays,
  cooldownField: s.cooldownField, cooldownCutoffTs: s.cooldownCutoffTs, shardField: s.shardField, shardCount: s.shardCount,
  noShards: s.noShards, csvMode: s.csvMode, csvEmails: s.csvEmails, csvChunks: s.csvChunks,
  baseAndClauses: s.baseAndClauses, attempt: s.attempt, maxAttempts: s.maxAttempts,
  shardsUsed: s.shardsUsed, collected: s.collected, totalMatching: s.totalMatching
} }];

const s = $input.first().json;
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const collected = Array.isArray(s.collected) ? s.collected : [];
// Oversample 5x: Format Output drops recently-invited profiles (cooldown) client-side and trims to sampleSize.
const want = Math.min(collected.length, Math.max(1, s.sampleSize * 5));
const sampled = shuffle(collected).slice(0, want);
if (sampled.length === 0) return [{ json: { __empty: true } }];
return sampled.map(r => ({ json: { cio_id: r.cio_id || null, cust_id: r.id || null, email: r.email || null } }));

// One person can own several Customer.io profiles with the same email (about 1 in 5 in the n8n users pool, measured 2026-10-06).
// Cooldown and unsubscribe are decided per person, so every profile sharing a sampled email is looked up here, with no other filter.
const samples = $('Sample Candidates').all().map(i => i.json).filter(x => x && !x.__empty);
const fetched = $input.all().map(i => i.json || {});
const seen = new Set();
const emails = [];
samples.forEach((sm, idx) => {
  const a = (fetched[idx] && fetched[idx].customer && fetched[idx].customer.attributes) || {};
  const e = String(a.email || sm.email || '').trim().toLowerCase();
  if (/^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$/.test(e) && !seen.has(e)) { seen.add(e); emails.push(e); }
});
// CSV: include every uploaded email, also those the search did not return, so the card can tell "in cooldown" from "not in Customer.io"
const state = $('Collect & Check').first().json || {};
if (state.csvMode) for (const raw of (state.csvEmails || [])) {
  const e = String(raw || '').trim().toLowerCase();
  if (/^[^@\s,;<>]+@[^@\s,;<>]+\.[^@\s,;<>]+$/.test(e) && !seen.has(e)) { seen.add(e); emails.push(e); }
}
const chunks = [];
for (let i = 0; i < emails.length; i += 50) chunks.push(emails.slice(i, i + 50));
if (!chunks.length) chunks.push(['nobody@invalid.invalid']); // matches nothing, keeps the chain running
return chunks.map(chunk => ({ json: { emails: chunk, body: JSON.stringify({ filter: { or: chunk.map(e => ({ attribute: { field: 'email', operator: 'eq', value: e } })) } }) } }));

// Same emails again, this time only the profiles sitting in the cooldown segment (invited by the wizard or by a research broadcast).
// Read from Config, not from the search state: Prep Retry does not carry cooldownSegmentId across retries.
const segId = Number(($('Load Config').first().json || {}).cooldownSegmentId) || 0;
const chunks = $('Build Email Lookups').all().map(i => (i.json && i.json.emails) || []).filter(c => c.length);
const nothing = { attribute: { field: 'email', operator: 'eq', value: 'nobody@invalid.invalid' } };
if (!chunks.length || segId <= 0) return [{ json: { emails: [], body: JSON.stringify({ filter: nothing }) } }];
return chunks.map(chunk => ({ json: { emails: chunk, body: JSON.stringify({ filter: { and: [ { segment: { id: segId } }, { or: chunk.map(e => ({ attribute: { field: 'email', operator: 'eq', value: e } })) } ] } }) } }));

// Sibling = a profile sharing a sampled email that the search itself did not return (filtered out server-side, or simply not sampled).
// Their attributes are needed for the per-person rules in Format Output.
const samples = $('Sample Candidates').all().map(i => i.json).filter(x => x && !x.__empty);
const sampledIds = new Set(samples.map(s => s.cio_id).filter(Boolean));
// Only twins of sampled people are read: the lookup may also cover uploaded emails the search did not return
const sampledEmails = new Set(samples.map(s => String(s.email || '').trim().toLowerCase()).filter(Boolean));
$('Fetch Attributes').all().forEach(i => { const e = i.json && i.json.customer && i.json.customer.attributes && i.json.customer.attributes.email; if (e) sampledEmails.add(String(e).trim().toLowerCase()); });
const pages = $('Lookup Profiles By Email').all().map(i => i.json || {});
const seen = new Set();
const out = [];
for (const p of pages) {
  const ids = (p.body && p.body.identifiers) || [];
  if (!Array.isArray(ids)) continue;
  for (const r of ids) {
    if (!r || !r.cio_id || sampledIds.has(r.cio_id) || seen.has(r.cio_id)) continue;
    if (!sampledEmails.has(String(r.email || '').trim().toLowerCase())) continue;
    seen.add(r.cio_id);
    out.push({ json: { cio_id: r.cio_id, email: String(r.email || '').trim().toLowerCase() } });
  }
}
if (!out.length) return [{ json: { __none: true } }];
return out;
